323: func newGreenhouseContract(t *testing.T, f *workerTabsFixture) *greenhouseContract {
324: 	t.Helper()
325: 	install := exec.Command("go", "install", greenhouseModule+"@"+greenhouseVersion)
326: 	install.Env = setEnv(os.Environ(), "GOBIN", filepath.Join(f.root, "bin"))
327: 	if output, err := install.CombinedOutput(); err != nil {
328: 		t.Fatalf("install pinned Greenhouse: %v\n%s", err, output)
329: 	}
330: 	c := &greenhouseContract{f: f, ctl: filepath.Join(f.root, "home", "greenhouse-reviewer"), home: filepath.Join(f.home, "greenhouse")}
331: 	agent := filepath.Join(f.root, "home", "pi-agent")
332: 	for _, directory := range []string{c.ctl, agent, c.home} {
333: 		if err := os.MkdirAll(directory, 0o700); err != nil {
334: 			t.Fatal(err)
335: 		}
336: 	}
337: 	if err := os.WriteFile(filepath.Join(agent, "models.json"), []byte(`{"providers":{"fixture":{"models":[{"id":"model","reasoning":true}]}}}`), 0o600); err != nil {
338: 		t.Fatal(err)
339: 	}
340: 	if err := os.WriteFile(filepath.Join(f.root, "bin", "pi"), []byte(fmt.Sprintf(greenhouseFakeReviewer, c.ctl)), 0o700); err != nil {
341: 		t.Fatal(err)
342: 	}
343: 	backends := fmt.Sprintf(`{"version":2,"writable":{"reviewer":[%q]}}`, c.ctl)
344: 	if err := os.WriteFile(filepath.Join(c.home, "backends.json"), []byte(backends), 0o600); err != nil {
345: 		t.Fatal(err)
346: 	}
347: 	c.env = setEnv(f.leadEnv, "PI_CODING_AGENT_DIR", agent)
348: 	t.Cleanup(func() { c.stopDaemon(t) })
349: 	return c
350: }
