--- internal/greenhouse/protocol.go ---
1: // Package greenhouse is Posse's host adapter for Greenhouse review in host mode.
2: // It speaks AXI protocol version 2 to `greenhouse axi`, one request per
3: // invocation, against a daemon that Posse starts and places itself.
4: package greenhouse
5: 
6: import (
7: 	"bytes"
8: 	"context"
9: 	"encoding/json"
10: 	"errors"
11: 	"fmt"
12: 	"os/exec"
13: 	"strings"
14: )
15: 
16: // Protocol is the only AXI envelope version the adapter speaks. It never
17: // downgrades: host mode does not exist below version 2.
18: const Protocol = 2
19: 
20: // Range is an inclusive protocol version range.
21: type Range struct {
22: 	Min int `json:"min"`
23: 	Max int `json:"max"`
24: }
25: 
26: func (r Range) Includes(version int) bool { return r.Min <= version && version <= r.Max }
27: 
28: func (r Range) String() string {
29: 	if r.Min == r.Max {
30: 		return fmt.Sprint(r.Min)
31: 	}
32: 	return fmt.Sprintf("%d-%d", r.Min, r.Max)
33: }
34: 
35: // PosseRange is the protocol range this adapter accepts.
36: var PosseRange = Range{Min: Protocol, Max: Protocol}
37: 
38: // ProtocolError refuses a daemon whose range excludes the adapter's version.
39: type ProtocolError struct {
40: 	Daemon Range
41: }
42: 
43: func (e *ProtocolError) Error() string {
44: 	return fmt.Sprintf("the Greenhouse daemon speaks protocol %s and Posse needs protocol %s; Posse does not downgrade. Let its work settle, stop it and install a Greenhouse that speaks protocol %d", e.Daemon, PosseRange, Protocol)
45: }
46: 
47: // Host identifies the Posse host run, one per Task Member.
48: type Host struct {
49: 	Name string `json:"name"`
50: 	ID   string `json:"id"`
51: }
52: 
53: // Finding is one Greenhouse finding as host_result reports it.
54: type Finding struct {
55: 	ID          string `json:"id"`
56: 	Priority    string `json:"priority"`
57: 	Origin      string `json:"origin"`
58: 	File        string `json:"file"`
59: 	Start       int    `json:"start"`
60: 	End         int    `json:"end"`
61: 	Explanation string `json:"explanation"`
62: 	Action      string `json:"action"`
63: 	Rule        string `json:"rule"`
64: 	Head        string `json:"head"`
65: }
66: 
67: // HostResult is the exact-head review result of a host run.
68: type HostResult struct {
69: 	Grant        string    `json:"grant"`
70: 	ReviewID     string    `json:"review_id"`
71: 	Head         string    `json:"head"`
72: 	Target       string    `json:"target"`
73: 	ReviewBase   string    `json:"review_base"`
74: 	Status       string    `json:"status"`
75: 	Verdict      string    `json:"verdict"`
76: 	Current      bool      `json:"current"`
77: 	Findings     []Finding `json:"findings"`
78: 	RulesDigest  string    `json:"rules_digest"`
79: 	ConfigDigest string    `json:"config_digest"`
80: 	InputDigest  string    `json:"input_digest"`
81: 	Backend      string    `json:"backend"`
82: 	Model        string    `json:"model"`
83: 	Reason       string    `json:"reason"`
84: }
85: 
86: // Recovery is set while a run waits for recovery after an interruption.
87: type Recovery struct {
88: 	ID      string   `json:"id"`
89: 	Reason  string   `json:"reason"`
90: 	Options []string `json:"options"`
91: }
92: 
93: type run struct {
94: 	ID         string    `json:"id"`
95: 	Status     string    `json:"status"`
96: 	Candidate  string    `json:"candidate"`
97: 	HostGrants []string  `json:"host_grants"`
98: 	ReviewUsed int       `json:"review_used"`
99: 	Recovery   *Recovery `json:"recovery"`
100: }
101: 
102: type defaults struct {
103: 	Rules           []string `json:"rules"`
104: 	ReviewerBackend string   `json:"reviewer_backend"`
105: 	ReviewerModel   string   `json:"reviewer_model"`
106: }
107: 
108: type response struct {
109: 	Version    int         `json:"version"`
110: 	Outcome    string      `json:"outcome"`
111: 	Error      string      `json:"error"`
112: 	RunID      string      `json:"run_id"`
113: 	InputID    string      `json:"input_id"`
114: 	GateID     string      `json:"gate_id"`
115: 	Token      string      `json:"token"`
116: 	RulesReady bool        `json:"rules_ready"`
117: 	Run        *run        `json:"run"`
118: 	Defaults   *defaults   `json:"defaults"`
119: 	HostResult *HostResult `json:"host_result"`
120: 	Protocol   *Range      `json:"protocol"`
121: 	Stream     string      `json:"stream"`
122: 	Sequence   uint64      `json:"sequence"`
123: }
124: 
125: func (v response) refusal(op string) error {
126: 	if v.Outcome == "ok" {
127: 		return nil
128: 	}
129: 	if v.Protocol != nil && !v.Protocol.Includes(Protocol) {
130: 		return &ProtocolError{Daemon: *v.Protocol}
131: 	}
132: 	return fmt.Errorf("greenhouse %s %s: %s", op, v.Outcome, v.Error)
133: }
134: 
135: var errUnavailable = errors.New("greenhouse daemon unavailable")
136: 
137: func (d *Daemon) axi(ctx context.Context, dir string, request []byte) (response, error) {
138: 	command := exec.CommandContext(ctx, d.Binary, "axi")
139: 	command.Dir = dir
140: 	command.Env = d.environment()
141: 	command.Stdin = bytes.NewReader(request)
142: 	var stdout, stderr bytes.Buffer
143: 	command.Stdout, command.Stderr = &stdout, &stderr
144: 	runErr := command.Run()
145: 	var v response
146: 	if err := json.Unmarshal(stdout.Bytes(), &v); err != nil {
147: 		if runErr != nil {
148: 			return v, fmt.Errorf("greenhouse axi: %w: %s", runErr, strings.TrimSpace(stderr.String()))
149: 		}
150: 		return v, fmt.Errorf("greenhouse axi returned no envelope: %w", err)
151: 	}
152: 	if v.Outcome == "error" && strings.Contains(v.Error, "daemon unavailable") {
153: 		return v, fmt.Errorf("%w: %s", errUnavailable, v.Error)
154: 	}
155: 	if v.Outcome == "error" {
156: 		return v, fmt.Errorf("greenhouse axi error: %s", v.Error)
157: 	}
158: 	return v, nil
159: }
--- internal/greenhouse/round.go ---
1: package greenhouse
2: 
3: import (
4: 	"context"
5: 	"encoding/json"
6: 	"errors"
7: 	"fmt"
8: 	"os"
9: 	"os/exec"
10: 	"strings"
11: 	"time"
12: 
13: 	"github.com/thanhbinh1905/posse/internal/atomicfile"
14: )
15: 
16: // Settings selects the rules and reviewer passed to Greenhouse `apply`. Empty
17: // fields take the daemon's defaults.
18: type Settings struct {
19: 	Rules           []string
20: 	ReviewerBackend string
21: 	ReviewerModel   string
22: }
23: 
24: // Round asks Greenhouse for one exact-head review of a Task Member.
25: type Round struct {
26: 	Worktree string
27: 	Host     Host
28: 	// GrantPrefix is "<project>/t<seq>/<member>"; round n uses GrantPrefix/r<n>.
29: 	GrantPrefix string
30: 	Intent      string
31: 	Target      string
32: 	Settings    Settings
33: 	// Pending is the write-ahead record of the review request in flight, so a
34: 	// restarted Posse replays the same request instead of spending a new grant.
35: 	Pending string
36: 	Wait    time.Duration
37: 	// Checkpoint, when set, runs at named steps so tests can stop Posse there.
38: 	Checkpoint func(step string)
39: }
40: 
41: type Outcome string
42: 
43: const (
44: 	// Settled: the grant has a verdict; Result.Current says whether it still binds the head.
45: 	Settled Outcome = "settled"
46: 	// Stale: the head moved, so the result binds no head.
47: 	Stale Outcome = "stale"
48: 	// Paused: a backend pause; the same grant resumes later.
49: 	Paused Outcome = "paused"
50: 	// RecoveryRequired: the run parked after an interruption; no new grant until it is resolved.
51: 	RecoveryRequired Outcome = "recovery-required"
52: 	// Running: the wait ended before the review settled.
53: 	Running Outcome = "running"
54: )
55: 
56: type RoundResult struct {
57: 	Outcome  Outcome
58: 	Grant    string
59: 	RunID    string
60: 	Result   *HostResult
61: 	Recovery *Recovery
62: 	// Replayed is true when the review request was replayed for its receipt.
63: 	Replayed bool
64: }
65: 
66: type pendingReview struct {
67: 	Grant   string          `json:"grant"`
68: 	Request json.RawMessage `json:"request"`
69: }
70: 
71: // Review continues the Member's round in flight, or starts the next one.
72: func (d *Daemon) Review(ctx context.Context, round Round) (RoundResult, error) {
73: 	if _, err := d.Ensure(ctx); err != nil {
74: 		return RoundResult{}, err
75: 	}
76: 	v, err := d.attach(ctx, round)
77: 	if err != nil {
78: 		return RoundResult{}, err
79: 	}
80: 	pending, err := readPending(round.Pending)
81: 	if err != nil {
82: 		return RoundResult{}, err
83: 	}
84: 	if v.Run != nil && v.Run.Recovery != nil {
85: 		grant := ""
86: 		if pending != nil {
87: 			grant = pending.Grant
88: 		}
89: 		return RoundResult{Outcome: RecoveryRequired, Grant: grant, RunID: v.RunID, Recovery: v.Run.Recovery}, nil
90: 	}
91: 	if pending != nil {
92: 		return d.continueReview(ctx, round, v, *pending)
93: 	}
94: 	return d.startReview(ctx, round, v)
95: }
96: 
97: // ClearPending ends the round in flight once Posse has acted on its result.
98: func ClearPending(path string) error {
99: 	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
100: 		return err
101: 	}
102: 	return nil
103: }
104: 
105: func (d *Daemon) continueReview(ctx context.Context, round Round, v response, pending pendingReview) (RoundResult, error) {
106: 	delivered := v.HostResult != nil && v.HostResult.Grant == pending.Grant
107: 	replay, err := d.axi(ctx, round.Worktree, pending.Request)
108: 	if err != nil {
109: 		return RoundResult{}, err
110: 	}
111: 	if replay.Outcome != "ok" && !delivered {
112: 		// The request never reached the daemon and its envelope is stale.
113: 		if err := ClearPending(round.Pending); err != nil {
114: 			return RoundResult{}, err
115: 		}
116: 		return d.startReview(ctx, round, v)
117: 	}
118: 	if delivered && v.HostResult.Status == "paused" {
119: 		if _, err := d.call(ctx, round, v, pending.Grant, "resume", nil); err != nil {
120: 			return RoundResult{}, err
121: 		}
122: 	}
123: 	result, err := d.wait(ctx, round, pending.Grant)
124: 	result.Replayed = delivered && replay.Outcome == "ok"
125: 	return result, err
126: }
