128: func (d *Daemon) startReview(ctx context.Context, round Round, v response) (RoundResult, error) {
129: 	used := 0
130: 	if v.Run != nil {
131: 		used = len(v.Run.HostGrants)
132: 	}
133: 	grant := fmt.Sprintf("%s/r%d", round.GrantPrefix, used+1)
134: 	head, err := worktreeHead(ctx, round.Worktree)
135: 	if err != nil {
136: 		return RoundResult{}, err
137: 	}
138: 	if v.HostResult != nil || v.Run == nil || v.Run.Candidate != head {
139: 		if v, err = d.call(ctx, round, v, grant, "new", nil); err != nil {
140: 			return RoundResult{}, err
141: 		}
142: 	}
143: 	selected := round.Settings
144: 	if v.Defaults != nil {
145: 		if len(selected.Rules) == 0 {
146: 			selected.Rules = v.Defaults.Rules
147: 		}
148: 		if selected.ReviewerBackend == "" {
149: 			selected.ReviewerBackend, selected.ReviewerModel = v.Defaults.ReviewerBackend, v.Defaults.ReviewerModel
150: 		}
151: 	}
152: 	// Host mode ignores the limit, but apply refuses one below consumed usage.
153: 	limit := 1
154: 	if v.Run != nil {
155: 		limit += v.Run.ReviewUsed
156: 	}
157: 	settings := map[string]any{
158: 		"mode": "ask", "preset": "one-pass", "limit": limit, "rules": selected.Rules,
159: 		"reviewer_backend": selected.ReviewerBackend, "reviewer_model": selected.ReviewerModel,
160: 		"fixer_backend": selected.ReviewerBackend, "fixer_model": selected.ReviewerModel,
161: 	}
162: 	if v, err = d.call(ctx, round, v, grant, "apply", map[string]any{"settings": settings}); err != nil {
163: 		return RoundResult{}, err
164: 	}
165: 	if v, err = d.call(ctx, round, v, grant, "resolve-rules", nil); err != nil {
166: 		return RoundResult{}, err
167: 	}
168: 	if !v.RulesReady {
169: 		return RoundResult{}, fmt.Errorf("greenhouse rules %v did not load", selected.Rules)
170: 	}
171: 	if v, err = d.call(ctx, round, v, grant, "prepare", map[string]any{"intent": round.Intent, "target": round.Target}); err != nil {
172: 		return RoundResult{}, err
173: 	}
174: 	request, err := json.Marshal(d.request(round, v, grant, "review", map[string]any{"grant": grant}))
175: 	if err != nil {
176: 		return RoundResult{}, err
177: 	}
178: 	record, err := json.Marshal(pendingReview{Grant: grant, Request: request})
179: 	if err != nil {
180: 		return RoundResult{}, err
181: 	}
182: 	if err := atomicfile.Write(round.Pending, record, 0o600); err != nil {
183: 		return RoundResult{}, err
184: 	}
185: 	reviewed, err := d.axi(ctx, round.Worktree, request)
186: 	if err != nil {
187: 		return RoundResult{}, err
188: 	}
189: 	if err := reviewed.refusal("review"); err != nil {
190: 		_ = ClearPending(round.Pending)
191: 		return RoundResult{}, err
192: 	}
193: 	if round.Checkpoint != nil {
194: 		round.Checkpoint("review-sent")
195: 	}
196: 	return d.wait(ctx, round, grant)
197: }
