1: package greenhouse
2: 
3: import (
4: 	"context"
5: 	"encoding/json"
6: 	"errors"
7: 	"fmt"
8: 	"net"
9: 	"os"
10: 	"os/exec"
11: 	"path/filepath"
12: 	"strconv"
13: 	"strings"
14: 	"syscall"
15: 	"time"
16: 
17: 	"github.com/thanhbinh1905/posse/internal/atomicfile"
18: )
19: 
20: const (
21: 	stateFile = "posse-daemon.json"
22: 	logFile   = "posse-daemon.log"
23: )
24: 
25: // Daemon is the Posse-owned Greenhouse daemon. Home is GREENHOUSE_HOME, always
26: // <POSSE_HOME>/greenhouse, never the User's own Greenhouse home.
27: type Daemon struct {
28: 	Binary string
29: 	Home   string
30: 	// Env is the caller's environment. Task markers and Posse and Herdr
31: 	// variables are removed before the daemon or a client sees it.
32: 	Env []string
33: 	// InTask reports whether a process runs inside a Posse Task's cgroup or
34: 	// carries its marker.
35: 	InTask func(pid int) bool
36: }
37: 
38: // DaemonState is what Posse recorded about the daemon it placed.
39: type DaemonState struct {
40: 	PID    int    `json:"pid"`
41: 	Binary string `json:"binary"`
42: 	Range  Range  `json:"protocol"`
43: }
44: 
45: func HomeFor(posseHome string) string { return filepath.Join(posseHome, "greenhouse") }
46: 
47: func (d *Daemon) environment() []string {
48: 	env := make([]string, 0, len(d.Env)+1)
49: 	for _, entry := range d.Env {
50: 		key, _, _ := strings.Cut(entry, "=")
51: 		if strings.HasPrefix(key, "POSSE_") || strings.HasPrefix(key, "HERDR_") || key == "GREENHOUSE_HOME" ||
52: 			key == "GIT_DIR" || key == "GIT_WORK_TREE" || key == "GIT_INDEX_FILE" {
53: 			continue
54: 		}
55: 		env = append(env, entry)
56: 	}
57: 	return append(env, "GREENHOUSE_HOME="+d.Home)
58: }
59: 
60: // Ensure returns the running daemon, starting and probing it first if needed.
61: // It refuses a daemon whose protocol range excludes version 2.
62: func (d *Daemon) Ensure(ctx context.Context) (DaemonState, error) {
63: 	if err := d.refuseTaskCaller(); err != nil {
64: 		return DaemonState{}, err
65: 	}
66: 	if err := os.MkdirAll(d.Home, 0o700); err != nil {
67: 		return DaemonState{}, err
68: 	}
69: 	if err := os.Chmod(d.Home, 0o700); err != nil {
70: 		return DaemonState{}, err
71: 	}
72: 	pid, live := d.livePID()
73: 	if !live {
74: 		var err error
75: 		if pid, err = d.start(ctx); err != nil {
76: 			return DaemonState{}, err
77: 		}
78: 	}
79: 	if err := d.verifyPlacement(pid); err != nil {
80: 		_ = syscall.Kill(pid, syscall.SIGTERM)
81: 		return DaemonState{}, err
82: 	}
83: 	state, err := ReadState(d.Home)
84: 	if err != nil || state.PID != pid {
85: 		probed, err := d.probe(ctx)
86: 		if err != nil {
87: 			return DaemonState{}, err
88: 		}
89: 		state = DaemonState{PID: pid, Binary: d.Binary, Range: probed}
90: 		encoded, _ := json.Marshal(state)
91: 		if err := atomicfile.Write(filepath.Join(d.Home, stateFile), encoded, 0o600); err != nil {
92: 			return DaemonState{}, err
93: 		}
94: 	}
95: 	if !state.Range.Includes(Protocol) {
96: 		return state, &ProtocolError{Daemon: state.Range}
97: 	}
98: 	return state, nil
99: }
100: 
101: func ReadState(home string) (DaemonState, error) {
102: 	var state DaemonState
103: 	data, err := os.ReadFile(filepath.Join(home, stateFile))
104: 	if err != nil {
105: 		return state, err
106: 	}
107: 	return state, json.Unmarshal(data, &state)
108: }
109: 
110: // LivePID returns the PID of the daemon serving home and whether it is alive.
111: func LivePID(home string) (int, bool) {
112: 	return (&Daemon{Home: home}).livePID()
113: }
114: 
115: func (d *Daemon) livePID() (int, bool) {
116: 	data, err := os.ReadFile(filepath.Join(d.Home, "pid"))
117: 	if err != nil {
118: 		return 0, false
119: 	}
120: 	pid, err := strconv.Atoi(strings.TrimSpace(string(data)))
121: 	if err != nil || pid < 2 || syscall.Kill(pid, 0) != nil {
122: 		return pid, false
123: 	}
124: 	connection, err := net.DialTimeout("unix", filepath.Join(d.Home, "socket"), time.Second)
125: 	if err != nil {
126: 		return pid, false
127: 	}
128: 	_ = connection.Close()
129: 	return pid, true
130: }
131: 
132: func (d *Daemon) start(ctx context.Context) (int, error) {
133: 	log, err := os.OpenFile(filepath.Join(d.Home, logFile), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
134: 	if err != nil {
135: 		return 0, err
136: 	}
137: 	defer log.Close()
138: 	command := exec.Command(d.Binary, "daemon")
139: 	command.Dir = d.Home
140: 	command.Env = d.environment()
141: 	command.Stdout, command.Stderr = log, log
142: 	command.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
143: 	if err := command.Start(); err != nil {
144: 		return 0, fmt.Errorf("start Greenhouse daemon: %w", err)
145: 	}
146: 	exited := make(chan error, 1)
147: 	go func() { exited <- command.Wait() }()
148: 	deadline := time.NewTimer(10 * time.Second)
149: 	defer deadline.Stop()
150: 	ticker := time.NewTicker(20 * time.Millisecond)
151: 	defer ticker.Stop()
152: 	for {
153: 		if pid, live := d.livePID(); live {
154: 			return pid, nil
155: 		}
156: 		select {
157: 		case <-ctx.Done():
158: 			return 0, ctx.Err()
159: 		case <-deadline.C:
160: 			return 0, fmt.Errorf("the Greenhouse daemon did not open its socket within 10s; see %s", filepath.Join(d.Home, logFile))
161: 		case err := <-exited:
162: 			// A concurrent start may own the home; its socket appears shortly.
163: 			if pid, live := d.waitLive(2 * time.Second); live {
164: 				return pid, nil
165: 			}
166: 			return 0, fmt.Errorf("the Greenhouse daemon exited before serving: %v; see %s", err, filepath.Join(d.Home, logFile))
167: 		case <-ticker.C:
168: 		}
169: 	}
170: }
171: 
172: func (d *Daemon) waitLive(limit time.Duration) (int, bool) {
173: 	for deadline := time.Now().Add(limit); time.Now().Before(deadline); time.Sleep(20 * time.Millisecond) {
174: 		if pid, live := d.livePID(); live {
175: 			return pid, true
176: 		}
177: 	}
178: 	return 0, false
179: }
180: 
181: // probe reads the daemon's protocol range with a request outside every range,
182: // which a daemon refuses without changing anything. A daemon that answers
183: // without a protocol block predates negotiation and speaks only version 1.
184: func (d *Daemon) probe(ctx context.Context) (Range, error) {
185: 	v, err := d.axi(ctx, d.Home, []byte(`{"version":999,"op":"inspect"}`))
186: 	if err != nil {
187: 		return Range{}, err
188: 	}
189: 	if v.Protocol == nil {
190: 		return Range{Min: 1, Max: 1}, nil
191: 	}
192: 	return *v.Protocol, nil
193: }
194: 
195: // refuseTaskCaller keeps Greenhouse out of every Task: a daemon started from a
196: // Task process would join its cgroup and carry its marker, and that Task's
197: // Teardown would stop reviews of other Tasks.
198: func (d *Daemon) refuseTaskCaller() error {
199: 	if os.Getenv("POSSE_TASK_ID") != "" || d.InTask(os.Getpid()) {
200: 		return errors.New("a Task process never calls Greenhouse; run this from the Project Lead pane")
201: 	}
202: 	return nil
203: }
204: 
205: func (d *Daemon) verifyPlacement(pid int) error {
206: 	if d.InTask(pid) {
207: 		return fmt.Errorf("the Greenhouse daemon %d runs inside a Posse Task", pid)
208: 	}
209: 	environ, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "environ"))
210: 	if err != nil {
211: 		return nil
212: 	}
213: 	for entry := range strings.SplitSeq(string(environ), "\x00") {
214: 		if strings.HasPrefix(entry, "POSSE_TASK_ID=") {
215: 			return fmt.Errorf("the Greenhouse daemon %d carries a Task marker", pid)
216: 		}
217: 	}
218: 	return nil
219: }
