27: // RecordGreenhouseVerdict inserts a Greenhouse Verdict once per grant. It reads
28: // the Member head inside the write transaction and refuses the insert when the
29: // head differs from the reviewed one; it does not rely on Greenhouse's
30: // `current` flag. It reports false when the grant already has a Verdict.
31: func (db *DB) RecordGreenhouseVerdict(ctx context.Context, verdict Verdict, currentHead func(context.Context) (string, error)) (bool, error) {
32: 	if verdict.Grant == "" {
33: 		return false, errors.New("a Greenhouse Verdict needs its grant")
34: 	}
35: 	tx, err := db.beginTxWithRetry(ctx)
36: 	if err != nil {
37: 		return false, err
38: 	}
39: 	defer tx.Rollback()
40: 	var exists bool
41: 	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM verdicts WHERE grant_id=?)`, verdict.Grant).Scan(&exists); err != nil {
42: 		return false, err
43: 	}
44: 	if exists {
45: 		return false, nil
46: 	}
47: 	head, err := currentHead(ctx)
48: 	if err != nil {
49: 		return false, err
50: 	}
51: 	if head != verdict.Head {
52: 		return false, fmt.Errorf("%w: reviewed %s, now %s", ErrVerdictHeadMoved, verdict.Head, head)
53: 	}
54: 	if err := (greenhouseReviewProvider{}).RecordVerdict(ctx, tx, verdict); err != nil {
55: 		return false, err
56: 	}
57: 	return true, tx.Commit()
58: }
