func (f *workerTabsFixture) start(t *testing.T, taskID, title, name string) store.Task {
	t.Helper()
	brief := filepath.Join(f.root, name+".md")
	if err := os.WriteFile(brief, []byte("---\ntype: change\ntitle: "+title+"\ndone_when: the test tears it down\n---\nWait.\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if output := runPosse(t, f.binary, f.repo, f.leadEnv, "start", "--brief", brief, "--name", name); !strings.Contains(output, taskID) {
		t.Fatalf("start did not return %s: %s", taskID, output)
	}
	f.waitState(t, taskID, store.StateWorking)
	return f.task(t, taskID)
}

func (f *workerTabsFixture) task(t *testing.T, taskID string) store.Task {
	t.Helper()
	db, err := store.OpenReadOnly(f.home)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	task, err := db.Task(context.Background(), f.projectID, taskID)
	if err != nil {
		t.Fatal(err)
	}
	return task
}

