			return db.ProjectByID(ctx, task.ProjectID)
		}
	}
	if project, found, err := s.projectForHomeFolder(ctx, db, dir); err != nil || found {
		return project, err
	}
	home, err := s.homePath()
	if err != nil {
		return store.Project{}, err
	}
	projectHome := filepath.Join(resolvedPath(home), "projects", "<name>")
