+
+func (c *greenhouseContract) invocations(t *testing.T) int {
+	t.Helper()
+	data, err := os.ReadFile(filepath.Join(c.ctl, "invocations"))
+	if os.IsNotExist(err) {
+		return 0
+	}
+	if err != nil {
+		t.Fatal(err)
+	}
+	return strings.Count(string(data), "\n")
+}
