+func (c *greenhouseContract) waitInvocations(t *testing.T, want int) {
+	t.Helper()
+	if !waitForCondition(60*time.Second, func() bool { return c.invocations(t) >= want }) {
+		t.Fatalf("reviewer invocations = %d, want %d", c.invocations(t), want)
+	}
+}
