271: // call sends one host mutation. Its action ID names the grant, the operation
272: // and the run token it expects, so an identical retry replays its receipt.
273: func (d *Daemon) call(ctx context.Context, round Round, v response, grant, op string, extra map[string]any) (response, error) {
274: 	request, err := json.Marshal(d.request(round, v, grant, op, extra))
275: 	if err != nil {
276: 		return v, err
277: 	}
278: 	next, err := d.axi(ctx, round.Worktree, request)
279: 	if err != nil {
280: 		return next, err
281: 	}
282: 	return next, next.refusal(op)
283: }
