249: 		c.setMode(t, "clean")
250: 		result := c.review(t)
251: 		c.requireRecorded(t, result, head, "clean", 0)
252: 		if result["grant"] != paused["grant"] || len(c.hostGrants(t)) != grants {
253: 			t.Fatalf("the paused review did not resume under its grant: paused %v, result %v", paused, result)
254: 		}
