+		done := c.reviewAsync(c.env)
+		c.waitInvocations(t, invocations+1)
+		moved := c.authorCommit(t)
+		c.release(t)
+		result := c.finish(t, done)
+		c.requireRecorded(t, result, moved, "clean", 0)
+		if refused, _ := result["refused"].([]any); len(refused) != 1 {
