198: // greenhouseBlocking counts findings at or above blockAt. An unknown priority blocks.
199: func greenhouseBlocking(findings []greenhouse.Finding, blockAt string) int {
200: 	rank := map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}
201: 	threshold := rank[blockAt]
202: 	blocking := 0
203: 	for _, finding := range findings {
204: 		if priority, known := rank[finding.Priority]; !known || priority <= threshold {
205: 			blocking++
206: 		}
207: 	}
208: 	return blocking
209: }
