283: // posseTasks lists every Task of this Posse home whose processes may still run.
284: func posseTasks(ctx context.Context, db *store.DB) ([]store.Task, error) {
285: 	projects, err := db.Projects(ctx)
286: 	if err != nil {
287: 		return nil, err
288: 	}
289: 	var tasks []store.Task
290: 	for _, project := range projects {
291: 		projectTasks, err := db.Tasks(ctx, project.ID, true)
292: 		if err != nil {
293: 			return nil, err
294: 		}
295: 		for _, task := range projectTasks {
296: 			if task.State != store.StateTornDown {
297: 				tasks = append(tasks, task)
298: 			}
299: 		}
300: 	}
301: 	return tasks, nil
302: }
