304: // greenhouseDaemonCheck reports the protocol range Posse recorded when it placed
305: // the daemon. It never calls Greenhouse.
306: func greenhouseDaemonCheck(home string) (name, status, detail, action string) {
307: 	name = "Greenhouse daemon"
308: 	greenhouseHome := greenhouse.HomeFor(home)
309: 	pid, live := greenhouse.LivePID(greenhouseHome)
310: 	if !live {
311: 		return name, "ok", "not running; Posse starts it in " + greenhouseHome + " when it requests a Greenhouse review", ""
312: 	}
313: 	state, err := greenhouse.ReadState(greenhouseHome)
314: 	if err != nil || state.PID != pid {
315: 		return name, "warn", fmt.Sprintf("PID %d serves %s, but Posse has no protocol record for it", pid, greenhouseHome), "Request a Greenhouse review to probe it again"
316: 	}
317: 	if !state.Range.Includes(greenhouse.Protocol) {
318: 		return name, "fail", fmt.Sprintf("PID %d speaks protocol %s; Posse needs protocol %s", pid, state.Range, greenhouse.PosseRange), "Let its work settle, stop it with SIGTERM to PID " + strconv.Itoa(pid) + " and install a Greenhouse that speaks protocol " + strconv.Itoa(greenhouse.Protocol)
319: 	}
320: 	return name, "ok", fmt.Sprintf("PID %d speaks protocol %s; Posse uses %d", pid, state.Range, greenhouse.Protocol), ""
321: }
