16: // Settings selects the rules and reviewer passed to Greenhouse `apply`. Empty
17: // fields take the daemon's defaults.
18: type Settings struct {
19: 	Rules           []string
20: 	ReviewerBackend string
21: 	ReviewerModel   string
22: }
23: 
24: // Round asks Greenhouse for one exact-head review of a Task Member.
25: type Round struct {
26: 	Worktree string
27: 	Host     Host
28: 	// GrantPrefix is "<project>/t<seq>/<member>"; round n uses GrantPrefix/r<n>.
29: 	GrantPrefix string
30: 	Intent      string
31: 	Target      string
32: 	Settings    Settings
33: 	// Pending is the write-ahead record of the review request in flight, so a
34: 	// restarted Posse replays the same request instead of spending a new grant.
35: 	Pending string
36: 	Wait    time.Duration
37: 	// Checkpoint, when set, runs at named steps so tests can stop Posse there.
38: 	Checkpoint func(step string)
39: }
40: 
41: type Outcome string
42: 
43: const (
44: 	// Settled: the grant has a verdict; Result.Current says whether it still binds the head.
45: 	Settled Outcome = "settled"
46: 	// Stale: the head moved, so the result binds no head.
47: 	Stale Outcome = "stale"
48: 	// Paused: a backend pause; the same grant resumes later.
49: 	Paused Outcome = "paused"
50: 	// RecoveryRequired: the run parked after an interruption; no new grant until it is resolved.
51: 	RecoveryRequired Outcome = "recovery-required"
52: 	// Running: the wait ended before the review settled.
53: 	Running Outcome = "running"
54: )
55: 
56: type RoundResult struct {
57: 	Outcome  Outcome
58: 	Grant    string
59: 	RunID    string
60: 	Result   *HostResult
61: 	Recovery *Recovery
62: 	// Replayed is true when the review request was replayed for its receipt.
63: 	Replayed bool
64: }
65: 
66: type pendingReview struct {
67: 	Grant   string          `json:"grant"`
68: 	Request json.RawMessage `json:"request"`
69: }
70: 
71: // Review continues the Member's round in flight, or starts the next one.
72: func (d *Daemon) Review(ctx context.Context, round Round) (RoundResult, error) {
73: 	if _, err := d.Ensure(ctx); err != nil {
74: 		return RoundResult{}, err
75: 	}
76: 	v, err := d.attach(ctx, round)
77: 	if err != nil {
78: 		return RoundResult{}, err
79: 	}
80: 	pending, err := readPending(round.Pending)
81: 	if err != nil {
82: 		return RoundResult{}, err
83: 	}
84: 	if v.Run != nil && v.Run.Recovery != nil {
85: 		grant := ""
86: 		if pending != nil {
87: 			grant = pending.Grant
88: 		}
89: 		return RoundResult{Outcome: RecoveryRequired, Grant: grant, RunID: v.RunID, Recovery: v.Run.Recovery}, nil
90: 	}
91: 	if pending != nil {
92: 		return d.continueReview(ctx, round, v, *pending)
93: 	}
94: 	return d.startReview(ctx, round, v)
95: }
96: 
97: // ClearPending ends the round in flight once Posse has acted on its result.
98: func ClearPending(path string) error {
99: 	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
100: 		return err
101: 	}
102: 	return nil
103: }
104: 
105: func (d *Daemon) continueReview(ctx context.Context, round Round, v response, pending pendingReview) (RoundResult, error) {
106: 	delivered := v.HostResult != nil && v.HostResult.Grant == pending.Grant
107: 	replay, err := d.axi(ctx, round.Worktree, pending.Request)
108: 	if err != nil {
109: 		return RoundResult{}, err
110: 	}
111: 	if replay.Outcome != "ok" && !delivered {
112: 		// The request never reached the daemon and its envelope is stale.
113: 		if err := ClearPending(round.Pending); err != nil {
114: 			return RoundResult{}, err
115: 		}
116: 		return d.startReview(ctx, round, v)
117: 	}
118: 	if delivered && v.HostResult.Status == "paused" {
119: 		if _, err := d.call(ctx, round, v, pending.Grant, "resume", nil); err != nil {
120: 			return RoundResult{}, err
121: 		}
122: 	}
123: 	result, err := d.wait(ctx, round, pending.Grant)
124: 	result.Replayed = delivered && replay.Outcome == "ok"
125: 	return result, err
126: }
127: 
128: func (d *Daemon) startReview(ctx context.Context, round Round, v response) (RoundResult, error) {
129: 	used := 0
130: 	if v.Run != nil {
131: 		used = len(v.Run.HostGrants)
132: 	}
133: 	grant := fmt.Sprintf("%s/r%d", round.GrantPrefix, used+1)
134: 	head, err := worktreeHead(ctx, round.Worktree)
135: 	if err != nil {
136: 		return RoundResult{}, err
137: 	}
138: 	if v.HostResult != nil || v.Run == nil || v.Run.Candidate != head {
139: 		if v, err = d.call(ctx, round, v, grant, "new", nil); err != nil {
140: 			return RoundResult{}, err
141: 		}
142: 	}
143: 	selected := round.Settings
144: 	if v.Defaults != nil {
145: 		if len(selected.Rules) == 0 {
146: 			selected.Rules = v.Defaults.Rules
147: 		}
148: 		if selected.ReviewerBackend == "" {
149: 			selected.ReviewerBackend, selected.ReviewerModel = v.Defaults.ReviewerBackend, v.Defaults.ReviewerModel
150: 		}
151: 	}
152: 	// Host mode ignores the limit, but apply refuses one below consumed usage.
153: 	limit := 1
154: 	if v.Run != nil {
155: 		limit += v.Run.ReviewUsed
156: 	}
157: 	settings := map[string]any{
158: 		"mode": "ask", "preset": "one-pass", "limit": limit, "rules": selected.Rules,
159: 		"reviewer_backend": selected.ReviewerBackend, "reviewer_model": selected.ReviewerModel,
160: 		"fixer_backend": selected.ReviewerBackend, "fixer_model": selected.ReviewerModel,
161: 	}
162: 	if v, err = d.call(ctx, round, v, grant, "apply", map[string]any{"settings": settings}); err != nil {
163: 		return RoundResult{}, err
164: 	}
165: 	if v, err = d.call(ctx, round, v, grant, "resolve-rules", nil); err != nil {
166: 		return RoundResult{}, err
167: 	}
168: 	if !v.RulesReady {
169: 		return RoundResult{}, fmt.Errorf("greenhouse rules %v did not load", selected.Rules)
170: 	}
171: 	if v, err = d.call(ctx, round, v, grant, "prepare", map[string]any{"intent": round.Intent, "target": round.Target}); err != nil {
172: 		return RoundResult{}, err
173: 	}
174: 	request, err := json.Marshal(d.request(round, v, grant, "review", map[string]any{"grant": grant}))
175: 	if err != nil {
176: 		return RoundResult{}, err
177: 	}
178: 	record, err := json.Marshal(pendingReview{Grant: grant, Request: request})
179: 	if err != nil {
180: 		return RoundResult{}, err
181: 	}
182: 	if err := atomicfile.Write(round.Pending, record, 0o600); err != nil {
183: 		return RoundResult{}, err
184: 	}
185: 	reviewed, err := d.axi(ctx, round.Worktree, request)
186: 	if err != nil {
187: 		return RoundResult{}, err
188: 	}
189: 	if err := reviewed.refusal("review"); err != nil {
190: 		_ = ClearPending(round.Pending)
191: 		return RoundResult{}, err
192: 	}
193: 	if round.Checkpoint != nil {
194: 		round.Checkpoint("review-sent")
195: 	}
196: 	return d.wait(ctx, round, grant)
197: }
198: 
199: // wait follows the run until the grant settles, pauses, parks or goes stale.
200: // A daemon that disappears is started again and followed from its store.
201: func (d *Daemon) wait(ctx context.Context, round Round, grant string) (RoundResult, error) {
202: 	deadline := time.Now().Add(round.Wait)
203: 	stream, sequence := "", uint64(0)
204: 	for {
205: 		v, err := d.attach(ctx, round)
206: 		if errors.Is(err, errUnavailable) {
207: 			if _, err := d.Ensure(ctx); err != nil {
208: 				return RoundResult{}, err
209: 			}
210: 			continue
211: 		}
212: 		if err != nil {
213: 			return RoundResult{}, err
214: 		}
215: 		result := RoundResult{Grant: grant, RunID: v.RunID, Result: v.HostResult}
216: 		if v.Run != nil && v.Run.Recovery != nil {
217: 			result.Outcome, result.Recovery = RecoveryRequired, v.Run.Recovery
218: 			return result, nil
219: 		}
220: 		if hr := v.HostResult; hr != nil && hr.Grant == grant {
221: 			switch {
222: 			case !hr.Current && hr.Status == "running":
223: 				// Greenhouse refuses a successor while the stale review runs. A
224: 				// refused cancel means the review settled meanwhile.
225: 				request, _ := json.Marshal(d.request(round, v, grant, "cancel", nil))
226: 				if _, err := d.axi(ctx, round.Worktree, request); err != nil && !errors.Is(err, errUnavailable) {
227: 					return RoundResult{}, err
228: 				}
229: 				continue
230: 			case !hr.Current && hr.Status == "cancelling":
231: 			case !hr.Current:
232: 				result.Outcome = Stale
233: 				return result, nil
234: 			case hr.Verdict != "":
235: 				result.Outcome = Settled
236: 				return result, nil
237: 			case hr.Status == "paused":
238: 				result.Outcome = Paused
239: 				return result, nil
240: 			}
241: 		}
242: 		remaining := time.Until(deadline)
243: 		if remaining <= 0 {
244: 			result.Outcome = Running
245: 			return result, nil
246: 		}
247: 		if stream == "" {
248: 			stream, sequence = v.Stream, v.Sequence
249: 		}
250: 		wait := min(remaining, 2*time.Second)
251: 		request, _ := json.Marshal(map[string]any{"version": Protocol, "op": "watch", "stream": stream, "after": sequence, "wait_ms": wait.Milliseconds()})
252: 		watched, err := d.axi(ctx, round.Worktree, request)
253: 		if err != nil || watched.Stream == "" {
254: 			time.Sleep(100 * time.Millisecond)
255: 			stream = ""
256: 			continue
257: 		}
258: 		stream, sequence = watched.Stream, watched.Sequence
259: 	}
260: }
261: 
262: func (d *Daemon) attach(ctx context.Context, round Round) (response, error) {
263: 	request, _ := json.Marshal(map[string]any{"version": Protocol, "op": "attach", "host": round.Host})
264: 	v, err := d.axi(ctx, round.Worktree, request)
265: 	if err != nil {
266: 		return v, err
267: 	}
268: 	return v, v.refusal("attach")
269: }
270: 
271: // call sends one host mutation. Its action ID names the grant, the operation
272: // and the run token it expects, so an identical retry replays its receipt.
273: func (d *Daemon) call(ctx context.Context, round Round, v response, grant, op string, extra map[string]any) (response, error) {
274: 	request, err := json.Marshal(d.request(round, v, grant, op, extra))
275: 	if err != nil {
276: 		return v, err
277: 	}
278: 	next, err := d.axi(ctx, round.Worktree, request)
279: 	if err != nil {
280: 		return next, err
281: 	}
282: 	return next, next.refusal(op)
283: }
284: 
285: func (d *Daemon) request(round Round, v response, grant, op string, extra map[string]any) map[string]any {
286: 	q := map[string]any{
287: 		"version": Protocol, "op": op, "host": round.Host,
288: 		"run_id": v.RunID, "input_id": v.InputID, "gate_id": v.GateID, "expected": v.Token,
289: 		"action_id": grant + "/" + op + "/" + v.Token, "reason": "Posse host review " + grant,
290: 	}
291: 	for key, value := range extra {
292: 		q[key] = value
293: 	}
294: 	return q
295: }
296: 
297: func readPending(path string) (*pendingReview, error) {
298: 	data, err := os.ReadFile(path)
299: 	if errors.Is(err, os.ErrNotExist) {
300: 		return nil, nil
301: 	}
302: 	if err != nil {
303: 		return nil, err
304: 	}
305: 	var pending pendingReview
306: 	if err := json.Unmarshal(data, &pending); err != nil || pending.Grant == "" || len(pending.Request) == 0 {
307: 		return nil, fmt.Errorf("unreadable Greenhouse round record %s", path)
308: 	}
309: 	return &pending, nil
310: }
311: 
312: func worktreeHead(ctx context.Context, worktree string) (string, error) {
313: 	output, err := exec.CommandContext(ctx, "git", "-C", worktree, "rev-parse", "HEAD").Output()
314: 	if err != nil {
315: 		return "", fmt.Errorf("read the head of %s: %w", worktree, err)
316: 	}
317: 	return strings.TrimSpace(string(output)), nil
318: }
